    let isHi = true, isLo = true;
    for (let j = i - left; j <= i + right; j++) {
      if (j === i) continue;
      if (cs[j].h >= cs[i].h) isHi = false;
      if (cs[j].l <= cs[i].l) isLo = false;
    }
    if (isHi) highs.push({ i, p: cs[i].h });
    if (isLo) lows.push({ i, p: cs[i].l });
